question.answer:
from pathlib import PurePosixPath


def halve_steps(value: int) -> list[int]:
    steps: list[int] = []
    while (value := value // 2) > 0:
        steps.append(value)
    return steps


def csv_names(paths: list[str]) -> list[str]:
    return [pure.name for path in paths if (pure := PurePosixPath(path)).suffix == ".csv"]


def parts_of(path: str) -> str:
    pure = PurePosixPath(path)
    return f"{pure.parent} | {pure.name} | {pure.stem} | {pure.suffix}"


def as_json(path: str) -> str:
    return str(PurePosixPath(path).with_suffix(".json"))


def joined(folder: str, name: str) -> str:
    return str(PurePosixPath(folder) / name)

from collections.abc import Callable, Iterator, Sized

type Result[T] = T | None
type Channel = tuple[str, float]


def first[T](items: list[T]) -> T | None:
    for item in items:
        return item
    return None


def widest[T: Sized](items: list[T]) -> Result[T]:
    if not items:
        return None
    return max(items, key=len)


def total[T: (int, float)](values: list[T]) -> T:
    running = values[0]
    for value in values[1:]:
        running = running + value
    return running


def apply_all[T, R](items: list[T], func: Callable[[T], R]) -> list[R]:
    return [func(item) for item in items]


class Stack[T]:
    def __init__(self) -> None:
        self._items: list[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        return self._items.pop()

    def peek(self) -> Result[T]:
        return self._items[-1] if self._items else None

    def __len__(self) -> int:
        return len(self._items)

    def __iter__(self) -> Iterator[T]:
        return iter(self._items)

