from collections.abc import Iterator
from itertools import batched
from pathlib import PurePosixPath

# ----------------------------------------------------------------------
# Supplied. Do not change it. The tests run it beside yours and compare.
# ----------------------------------------------------------------------
def summarise_old(paths, readings, defaults, overrides, size):
    settings = dict(defaults)
    for key in overrides:
        settings[key] = overrides[key]

    names = []
    for path in paths:
        base = path.split("/")[-1]
        if base.startswith("raw_"):
            base = base[4:]
        if base.endswith(".csv"):
            base = base[:-4]
        names.append(base)

    groups = []
    group = []
    for value in readings:
        group.append(value)
        if len(group) == size:
            groups.append(tuple(group))
            group = []
    if group:
        groups.append(tuple(group))

    return {"settings": settings, "names": names, "groups": groups}
# ----------------------------------------------------------------------
# End of the supplied block.
# ----------------------------------------------------------------------


def summarise(paths: list[str], readings: list[int], defaults: dict[str, int],
              overrides: dict[str, int], size: int) -> dict[str, object]:
    return {
        "settings": defaults | overrides,
        "names": [PurePosixPath(path).name.removeprefix("raw_").removesuffix(".csv")
                  for path in paths],
        "groups": list(batched(readings, size)),
    }


def output_path(source: str, folder: str) -> str:
    pure = PurePosixPath(source)
    trimmed = pure.stem.removeprefix("raw_")
    return str((pure.parent / folder / trimmed).with_suffix(".json"))


def apply_overrides(config: dict[str, int], overrides: dict[str, int]) -> None:
    config |= overrides


def drain(source: Iterator[float]) -> list[float]:
    kept: list[float] = []
    while (value := next(source, None)) is not None:
        kept.append(value)
    return kept


def flagged(lines: list[str]) -> list[str]:
    return [code for line in lines if (code := line.removeprefix("ERR-")) != line]
